#!/usr/bin/env python3
"""Generate a byte-preserving kernel header for the audited SOF image."""

from __future__ import annotations

import hashlib
import pathlib
import sys


def generate(source: pathlib.Path, destination: pathlib.Path) -> None:
    payload = source.read_bytes()
    digest = hashlib.sha256(payload).hexdigest()
    rows = []
    for offset in range(0, len(payload), 16):
        rows.append("    " + ", ".join(
            f"0x{byte:02x}" for byte in payload[offset:offset + 16]
        ) + ",")
    text = (
        "// Generated by generate_firmware_kernel_header.py; do not edit.\n"
        "#pragma once\n\n#include <stddef.h>\n#include <stdint.h>\n\n"
        "namespace sof::ipc4::kernel {\n"
        "alignas(128) const uint8_t kSofFirmwareImage[] = {\n"
        + "\n".join(rows)
        + "\n};\n"
        "constexpr size_t kSofFirmwareImageBytes = sizeof(kSofFirmwareImage);\n"
        f'constexpr char kSofFirmwareImageSha256[] = "{digest}";\n'
        "} // namespace sof::ipc4::kernel\n"
    )
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_text(text, encoding="ascii")
    print(f"generated={destination} bytes={len(payload)} sha256={digest}")


if __name__ == "__main__":
    if len(sys.argv) != 3:
        raise SystemExit("usage: generate_firmware_kernel_header.py INPUT OUTPUT")
    generate(pathlib.Path(sys.argv[1]), pathlib.Path(sys.argv[2]))
